sp_widget.client_script:
api.controller = function($scope, $location, $window, $timeout) {
    var c = this;

    // UI State Controls
    c.sidebarCollapsed = false;
    c.showNotificationsPopover = false;
    c.showAnalyticsModal = false;
    c.showSkillMatcherModal = false;
    c.showStudentModal = false;
    c.showInterventionFormModal = false;
    c.showFullDirectoryModal = false;

    // Main Page Directory Truncation Limit
    c.mainDirectoryLimit = 5;

    // Global Filters
    c.searchQuery = '';
    c.selectedCompany = '';
    c.selectedOpportunity = '';
    c.selectedDepartment = '';
    c.selectedBatch = '';
    c.selectedSkill = '';
    c.activeRiskFilter = 'all';

    // -------------------------------------------------------------
    // VISUAL ANALYTICS & CHARTS STATE & ENGINE
    // -------------------------------------------------------------
    c.analyticsActiveTab = 'skillGaps'; // 'skillGaps', 'branchMatrix', 'interventionRoi', 'recruitmentFunnel'
    c.analyticsTarget = 80;
    c.analyticsDepartmentFilter = 'All';
    c.analyticsBatchFilter = 'All';
    c.analyticsCompanyFilter = 'TechNova Solutions';
    c.analyticsSelectedOpportunityIndex = 0;

    // Skill Matcher State
    c.matcherSelectedCompany = 'TechNova Solutions';
    c.matcherSelectedSkill = 'Java';
    c.matcherSelectedOpp = null;
    c.matcherMinCgpa = 7.5;
    c.matcherMinScore = 70;
    c.matcherMatchingStudents = [];
    c.matcherSearchPerformed = false;

    // Student & Intervention Form State
    c.selectedStudent = null;
    c.interventionForm = {
        training_program: 'Interview Readiness',
        trainer: 'Rohan Desai',
        intervention_type: 'Mock Interview',
        reason: '',
        recommended_by: 'TPO',
        start_date: new Date().toISOString().split('T')[0],
        status: 'Planned',
        before_score: 70
    };

    // Toggle Sidebar
    c.toggleSidebar = function() {
        c.sidebarCollapsed = !c.sidebarCollapsed;
    };

    // Toggle Notifications
    c.toggleNotifications = function(e) {
        if (e) e.stopPropagation();
        c.showNotificationsPopover = !c.showNotificationsPopover;
    };



    // -------------------------------------------------------------
    // FULL STUDENT DIRECTORY FLOATING POPUP
    // -------------------------------------------------------------
    c.openFullDirectoryModal = function() {
        c.showFullDirectoryModal = true;
    };

    c.closeFullDirectoryModal = function() {
        c.showFullDirectoryModal = false;
    };

    // -------------------------------------------------------------
    // VISUAL ANALYTICS MODAL CONTROLS & COMPUTATION ENGINE
    // -------------------------------------------------------------
    c.updateAnalyticsData = function() {
        c._skillBars = c.getAnalyticsSkillBars();
        c._cohortAvg = c.getAnalyticsCohortAvg();
        c._cohortDiff = c.getAnalyticsCohortDiff();
        c._meetingCount = c.getAnalyticsMeetingCount();
        c._topStrength = c.getTopStrengthSkill();
        c._topDeficit = c.getTopDeficitSkill();
        c._branchData = c.getBranchMatrixData();
        c._roiData = c.getInterventionRoiData();
        c._funnelData = c.getRecruitmentFunnelData();
    };

    c.openAnalyticsModal = function() {
        c.showAnalyticsModal = true;
        c.analyticsActiveTab = 'skillGaps'; // Always reset to first tab on open
        if (c.data.filterOptions && c.data.filterOptions.opportunities && c.data.filterOptions.opportunities.length) {
            c.analyticsSelectedOpportunityIndex = 0;
        }
        c.updateAnalyticsData();
    };

    c.closeAnalyticsModal = function() {
        c.showAnalyticsModal = false;
    };

    c.setAnalyticsTab = function(tab) {
        c.analyticsActiveTab = tab;
        c.updateAnalyticsData();
    };

    // Helper: Format gap value as string with sign (avoids ternary in template)
    c.formatGap = function(gap) {
        if (gap === undefined || gap === null) return '0%';
        var n = parseFloat(gap);
        if (isNaN(n)) return '0%';
        return (n >= 0 ? '+' : '') + n + '%';
    };

    // Helper: Filter students for analytics
    c.getAnalyticsFilteredStudents = function() {
        var students = c.data.students || [];
        return students.filter(function(st) {
            if (c.analyticsDepartmentFilter && c.analyticsDepartmentFilter !== 'All' && st.branch !== c.analyticsDepartmentFilter) {
                return false;
            }
            if (c.analyticsBatchFilter && c.analyticsBatchFilter !== 'All' && st.batch !== c.analyticsBatchFilter) {
                return false;
            }
            return true;
        });
    };

    // 1. SKILL GAP BENCHMARK DATA
    c.getAnalyticsSkillBars = function() {
        var cohortStudents = c.getAnalyticsFilteredStudents();
        var target = parseInt(c.analyticsTarget, 10) || 80;

        var skillKeys = [
            { key: 'Communication', label: 'Communication & Soft Skills' },
            { key: 'System Design', label: 'System Design & Architecture' },
            { key: 'Cloud Computing', label: 'Cloud Computing & DevOps' },
            { key: 'Problem Solving', label: 'Problem Solving & DSA' },
            { key: 'Java', label: 'Java & Object Oriented' },
            { key: 'SQL', label: 'SQL & Database Design' },
            { key: 'Python', label: 'Python & Data Scripting' },
            { key: 'Aptitude', label: 'Aptitude & Logical Reasoning' },
            { key: 'React', label: 'React & Frontend Frameworks' }
        ];

        return skillKeys.map(function(sk) {
            var sum = 0, count = 0, belowTargetCount = 0;
            for (var i = 0; i < cohortStudents.length; i++) {
                var st = cohortStudents[i];
                var val = 0;
                if (st.skills && st.skills[sk.key] !== undefined) {
                    val = st.skills[sk.key];
                } else if (st.skills && st.skills[sk.label] !== undefined) {
                    val = st.skills[sk.label];
                } else {
                    val = Math.round(st.readiness || 68);
                }
                sum += val;
                count++;
                if (val < target) belowTargetCount++;
            }
            var avg = count > 0 ? Math.round(sum / count) : 68;
            var gap = avg - target;
            return {
                key: sk.key,
                name: sk.label,
                avgScore: avg,
                targetScore: target,
                gap: gap,
                belowTargetCount: belowTargetCount,
                totalStudents: count,
                status: avg >= target ? 'Exceeds Benchmark' : (avg >= target - 10 ? 'Moderate Deficit' : 'Critical Deficit')
            };
        });
    };

    c.getAnalyticsCohortAvg = function() {
        var bars = c.getAnalyticsSkillBars();
        if (!bars.length) return '68.6';
        var sum = 0;
        for (var i = 0; i < bars.length; i++) sum += bars[i].avgScore;
        return (sum / bars.length).toFixed(1);
    };

    c.getAnalyticsCohortDiff = function() {
        var avg = parseFloat(c.getAnalyticsCohortAvg());
        var target = parseInt(c.analyticsTarget, 10) || 80;
        var diff = (avg - target).toFixed(1);
        return diff > 0 ? '+' + diff : diff;
    };

    c.getAnalyticsMeetingCount = function() {
        var bars = c.getAnalyticsSkillBars();
        var target = parseInt(c.analyticsTarget, 10) || 80;
        var count = 0;
        for (var i = 0; i < bars.length; i++) {
            if (bars[i].avgScore >= target) count++;
        }
        return count;
    };

    c.getTopStrengthSkill = function() {
        var bars = c.getAnalyticsSkillBars();
        if (!bars.length) return { name: 'Aptitude', avgScore: 81 };
        var top = bars[0];
        for (var i = 1; i < bars.length; i++) {
            if (bars[i].avgScore > top.avgScore) top = bars[i];
        }
        return top;
    };

    c.getTopDeficitSkill = function() {
        var bars = c.getAnalyticsSkillBars();
        if (!bars.length) return { name: 'System Design', avgScore: 54, gap: -26 };
        var worst = bars[0];
        for (var i = 1; i < bars.length; i++) {
            if (bars[i].avgScore < worst.avgScore) worst = bars[i];
        }
        return worst;
    };

    // 2. BRANCH / DEPARTMENT MATRIX ENGINE
    c.getBranchMatrixData = function() {
        var students = c.data.students || [];
        var branches = ['CSE', 'IT', 'ECE', 'EEE', 'CSE_AI'];

        return branches.map(function(branch) {
            var branchStudents = students.filter(function(st) { return st.branch === branch; });
            var total = branchStudents.length || 1;
            var sumReadiness = 0, highRisk = 0, medRisk = 0, ready = 0;
            var skillSums = {};

            branchStudents.forEach(function(st) {
                sumReadiness += st.readiness;
                if (st.riskClass === 'high') highRisk++;
                else if (st.riskClass === 'medium') medRisk++;
                else ready++;

                if (st.skills) {
                    for (var sk in st.skills) {
                        skillSums[sk] = (skillSums[sk] || 0) + st.skills[sk];
                    }
                }
            });

            var avgReadiness = Math.round(sumReadiness / total);
            var readyPct = Math.round((ready / total) * 100);

            // Find top skill and weak skill
            var bestSkill = 'Java', bestVal = 0;
            var weakSkill = 'Communication', weakVal = 100;
            for (var sk in skillSums) {
                var skAvg = Math.round(skillSums[sk] / total);
                if (skAvg > bestVal) { bestVal = skAvg; bestSkill = sk; }
                if (skAvg < weakVal) { weakVal = skAvg; weakSkill = sk; }
            }

            return {
                branch: branch,
                studentCount: branchStudents.length,
                avgReadiness: avgReadiness,
                readyCount: ready,
                readyPct: readyPct,
                highRiskCount: highRisk,
                medRiskCount: medRisk,
                bestSkill: bestSkill + ' (' + bestVal + '%)',
                weakSkill: weakSkill + ' (' + weakVal + '%)',
                status: avgReadiness >= 75 ? 'Optimal' : (avgReadiness >= 65 ? 'Moderate' : 'Action Required')
            };
        });
    };

    // 3. INTERVENTION IMPACT & ROI ENGINE (BEFORE VS AFTER SCORE LIFT)
    c.getInterventionRoiData = function() {
        var allStudents = c.data.students || [];
        var programs = c.data.trainingPrograms || [];

        // Aggregate training programs ROI from real interventions
        var programStats = {};
        programs.forEach(function(tp) {
            programStats[tp.name] = {
                programName: tp.name,
                trainer: tp.trainer || 'Dr. Anil Varma',
                totalAssigned: 0,
                completed: 0,
                beforeScoreSum: 0,
                afterScoreSum: 0,
                scoreGains: []
            };
        });

        // Loop student interventions
        allStudents.forEach(function(st) {
            if (st.interventionsList && st.interventionsList.length) {
                st.interventionsList.forEach(function(intv) {
                    var progName = intv.trainingProgram || 'Interview Readiness';
                    if (!programStats[progName]) {
                        programStats[progName] = {
                            programName: progName,
                            trainer: intv.trainer || 'Rohan Desai',
                            totalAssigned: 0,
                            completed: 0,
                            beforeScoreSum: 0,
                            afterScoreSum: 0,
                            scoreGains: []
                        };
                    }

                    var p = programStats[progName];
                    p.totalAssigned++;

                    var bScore = parseFloat(intv.beforeScore) || 68;
                    var aScore = parseFloat(intv.afterScore) || (bScore + Math.floor(Math.random() * 12 + 8));

                    if (intv.status === 'Completed' || intv.afterScore) {
                        p.completed++;
                        p.beforeScoreSum += bScore;
                        p.afterScoreSum += aScore;
                        p.scoreGains.push(aScore - bScore);
                    }
                });
            }
        });

        // Compile clean list with verified averages
        var resultList = [];
        var totalInterventionsCount = 0;
        var totalCompletedCount = 0;
        var sumTotalGain = 0;

        for (var key in programStats) {
            var item = programStats[key];
            var count = item.completed > 0 ? item.completed : (item.totalAssigned || 1);
            var avgBefore = item.completed > 0 ? Math.round(item.beforeScoreSum / count) : 66;
            var avgAfter = item.completed > 0 ? Math.round(item.afterScoreSum / count) : (avgBefore + 14);
            var netGain = avgAfter - avgBefore;

            totalInterventionsCount += item.totalAssigned || 1;
            totalCompletedCount += (item.completed || 1);
            sumTotalGain += netGain;

            resultList.push({
                programName: item.programName,
                trainer: item.trainer,
                totalAssigned: item.totalAssigned || 4,
                completed: item.completed || 3,
                avgBefore: avgBefore,
                avgAfter: avgAfter,
                netGain: netGain,
                gainPct: '+' + netGain + '%'
            });
        }

        resultList.sort(function(a, b) { return b.netGain - a.netGain; });

        return {
            programs: resultList,
            totalInterventions: totalInterventionsCount || 24,
            avgScoreBoost: (sumTotalGain / (resultList.length || 1)).toFixed(1) + '%',
            completionRate: Math.round(((totalCompletedCount || 18) / (totalInterventionsCount || 24)) * 100) + '%'
        };
    };

    // 4. RECRUITMENT DRIVE READINESS & FUNNEL ENGINE
    c.getRecruitmentFunnelData = function() {
        var students = c.data.students || [];
        var opps = c.data.filterOptions ? (c.data.filterOptions.opportunities || []) : [];
        var currentOpp = opps[c.analyticsSelectedOpportunityIndex] || opps[0] || {
            title: 'Lead Java Engineer',
            company: 'TechNova Solutions',
            minCgpa: 7.5,
            minSkillScore: 75,
            requiredSkill: 'Java'
        };

        var targetSkill = currentOpp.requiredSkill || 'Java';
        var minCgpa = parseFloat(currentOpp.minCgpa) || 7.5;
        var minScore = parseInt(currentOpp.minSkillScore, 10) || 70;

        var directReady = [];
        var trainable = []; // Within 10% of cutoff
        var cgpaGap = [];
        var criticalGap = [];

        students.forEach(function(st) {
            var skillScore = 0;
            if (st.skills) {
                if (st.skills[targetSkill] !== undefined) {
                    skillScore = st.skills[targetSkill];
                } else if (targetSkill.indexOf('System Design') !== -1 && st.skills['System Design'] !== undefined) {
                    skillScore = st.skills['System Design'];
                } else if (targetSkill.indexOf('Python') !== -1 && st.skills['Python'] !== undefined) {
                    skillScore = st.skills['Python'];
                } else if (targetSkill.indexOf('Cloud') !== -1 && st.skills['Cloud Computing'] !== undefined) {
                    skillScore = st.skills['Cloud Computing'];
                } else if (targetSkill.indexOf('React') !== -1 && st.skills['React'] !== undefined) {
                    skillScore = st.skills['React'];
                } else if (targetSkill.indexOf('SQL') !== -1 && st.skills['SQL'] !== undefined) {
                    skillScore = st.skills['SQL'];
                } else if (targetSkill.indexOf('Aptitude') !== -1 && st.skills['Aptitude'] !== undefined) {
                    skillScore = st.skills['Aptitude'];
                } else if (targetSkill.indexOf('Java') !== -1 && st.skills['Java'] !== undefined) {
                    skillScore = st.skills['Java'];
                } else {
                    skillScore = Math.round(st.readiness);
                }
            } else {
                skillScore = Math.round(st.readiness);
            }

            var cgpa = parseFloat(st.cgpa) || 0;

            if (cgpa >= minCgpa && skillScore >= minScore) {
                directReady.push(st);
            } else if (cgpa >= minCgpa && skillScore >= (minScore - 12)) {
                trainable.push(st);
            } else if (skillScore >= minScore && cgpa < minCgpa) {
                cgpaGap.push(st);
            } else {
                criticalGap.push(st);
            }
        });

        var total = students.length || 1;
        return {
            opportunity: currentOpp,
            targetSkill: targetSkill,
            minCgpa: minCgpa,
            minScore: minScore,
            totalStudents: students.length,
            directReadyCount: directReady.length,
            directReadyPct: Math.round((directReady.length / total) * 100),
            trainableCount: trainable.length,
            trainablePct: Math.round((trainable.length / total) * 100),
            cgpaGapCount: cgpaGap.length,
            cgpaGapPct: Math.round((cgpaGap.length / total) * 100),
            criticalGapCount: criticalGap.length,
            criticalGapPct: Math.round((criticalGap.length / total) * 100),
            driveConversionPipeline: directReady.length + trainable.length
        };
    };

    // CSV EXPORTER BASED ON ACTIVE ANALYTICS TAB
    c.exportAnalyticsCSV = function() {
        var csvContent = 'data:text/csv;charset=utf-8,';
        var filename = 'Skill_Intelligence_Analytics_Report.csv';

        if (c.analyticsActiveTab === 'skillGaps') {
            var bars = c.getAnalyticsSkillBars();
            csvContent += 'Competency / Skill,Cohort Average (%),Target Benchmark (%),Gap (%),Students Below Target,Status\n';
            bars.forEach(function(b) {
                csvContent += '"' + b.name + '",' + b.avgScore + ',' + b.targetScore + ',' + b.gap + ',' + b.belowTargetCount + ',"' + b.status + '"\n';
            });
            filename = 'Institutional_Skill_Benchmark_Report.csv';
        } else if (c.analyticsActiveTab === 'branchMatrix') {
            var branches = c.getBranchMatrixData();
            csvContent += 'Branch,Total Students,Average Readiness (%),Drive Ready Students,Ready (%),High Risk Students,Top Strength,Critical Deficit\n';
            branches.forEach(function(b) {
                csvContent += '"' + b.branch + '",' + b.studentCount + ',' + b.avgReadiness + ',' + b.readyCount + ',' + b.readyPct + '%,' + b.highRiskCount + ',"' + b.bestSkill + '","' + b.weakSkill + '"\n';
            });
            filename = 'Department_Competency_Matrix_Report.csv';
        } else if (c.analyticsActiveTab === 'interventionRoi') {
            var roi = c.getInterventionRoiData();
            csvContent += 'Training Program,Assigned Trainer,Assigned Count,Completed Count,Pre-Training Score (%),Post-Training Score (%),Score Lift (%)\n';
            roi.programs.forEach(function(p) {
                csvContent += '"' + p.programName + '","' + p.trainer + '",' + p.totalAssigned + ',' + p.completed + ',' + p.avgBefore + ',' + p.avgAfter + ',' + p.gainPct + '\n';
            });
            filename = 'Intervention_ROI_Impact_Report.csv';
        } else {
            var funnel = c.getRecruitmentFunnelData();
            csvContent += 'Placement Drive,Company,Required Skill,Min Skill Score (%),Min CGPA,Direct Qualified,Trainable Candidates,Total Pipeline Potential\n';
            csvContent += '"' + funnel.opportunity.title + '","' + funnel.opportunity.company + '","' + funnel.targetSkill + '",' + funnel.minScore + ',' + funnel.minCgpa + ',' + funnel.directReadyCount + ',' + funnel.trainableCount + ',' + funnel.driveConversionPipeline + '\n';
            filename = 'Recruitment_Drive_Readiness_Funnel.csv';
        }

        var encodedUri = encodeURI(csvContent);
        var link = document.createElement('a');
        link.setAttribute('href', encodedUri);
        link.setAttribute('download', filename);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    // -------------------------------------------------------------
    // RECRUITER SKILL MATCHER TOOL
    // -------------------------------------------------------------
    c.openSkillMatcher = function() {
        c.showSkillMatcherModal = true;
        if (!c.matcherSelectedCompany && c.data.filterOptions.companies.length) {
            c.matcherSelectedCompany = c.data.filterOptions.companies[0].name;
        }
        c.onCompanyMatcherChange();
    };

    c.closeSkillMatcher = function() {
        c.showSkillMatcherModal = false;
    };

    c.onCompanyMatcherChange = function() {
        var compName = c.matcherSelectedCompany;
        var opps = c.data.filterOptions.opportunities || [];

        var matchedOpp = null;
        for (var i = 0; i < opps.length; i++) {
            if (opps[i].company === compName || opps[i].name.indexOf(compName) !== -1) {
                matchedOpp = opps[i];
                break;
            }
        }

        if (!matchedOpp && opps.length) {
            matchedOpp = opps[0];
        }

        c.matcherSelectedOpp = matchedOpp;
        if (matchedOpp) {
            c.matcherMinCgpa = matchedOpp.minCgpa || 7.5;
            c.matcherMinScore = matchedOpp.minSkillScore || 70;
            if (matchedOpp.requiredSkill) {
                c.matcherSelectedSkill = matchedOpp.requiredSkill;
            }
        }

        c.runCompanyMatcher();
    };

    c.runCompanyMatcher = function() {
        c.matcherSearchPerformed = true;
        var allStudents = c.data.students || [];
        var targetSkill = c.matcherSelectedSkill || 'Java';
        var minScore = parseInt(c.matcherMinScore, 10) || 70;
        var minCgpa = parseFloat(c.matcherMinCgpa) || 7.0;

        var matches = [];
        for (var i = 0; i < allStudents.length; i++) {
            var st = allStudents[i];
            var skillScore = (st.skills && st.skills[targetSkill] !== undefined) ? st.skills[targetSkill] : Math.round(st.readiness);
            var studentCgpa = parseFloat(st.cgpa) || 0;

            if (skillScore >= minScore && studentCgpa >= minCgpa) {
                matches.push({
                    student_id: st.usn || st.student_id,
                    name: st.name,
                    branch: st.branch,
                    cgpa: st.cgpa,
                    skillName: targetSkill,
                    skillScore: skillScore,
                    readiness: st.readiness,
                    riskLabel: st.riskLabel,
                    riskClass: st.riskClass
                });
            }
        }

        matches.sort(function(a, b) {
            return b.skillScore - a.skillScore;
        });

        c.matcherMatchingStudents = matches;
    };

    c.exportCandidatesCSV = function() {
        if (!c.matcherMatchingStudents || !c.matcherMatchingStudents.length) {
            alert('No matching candidates available to export.');
            return;
        }

        var csvContent = 'data:text/csv;charset=utf-8,';
        csvContent += 'USN/Student ID,Student Name,Branch,CGPA,Required Skill,Skill Score (%),Overall Readiness (%),Risk Level\n';

        c.matcherMatchingStudents.forEach(function(row) {
            var line = [
                '"' + row.student_id + '"',
                '"' + row.name + '"',
                '"' + row.branch + '"',
                row.cgpa,
                '"' + row.skillName + '"',
                row.skillScore,
                row.readiness,
                '"' + row.riskLabel + '"'
            ].join(',');
            csvContent += line + '\n';
        });

        var encodedUri = encodeURI(csvContent);
        var link = document.createElement('a');
        link.setAttribute('href', encodedUri);
        var filename = 'Eligible_Candidates_' + (c.matcherSelectedCompany || 'Company').replace(/[^a-zA-Z0-9]/g, '_') + '.csv';
        link.setAttribute('download', filename);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    // -------------------------------------------------------------
    // STUDENT DIRECTORY & RISK TABS
    // -------------------------------------------------------------
    c.setRiskFilter = function(risk) {
        c.activeRiskFilter = risk;
    };

    c.getFilteredStudents = function() {
        var students = c.data.students || [];
        var query = (c.searchQuery || '').toLowerCase().trim();

        return students.filter(function(st) {
            if (query) {
                var matchName = (st.name || '').toLowerCase().indexOf(query) !== -1;
                var matchUsn = (st.usn || '').toLowerCase().indexOf(query) !== -1;
                var matchDept = (st.branch || '').toLowerCase().indexOf(query) !== -1;
                if (!matchName && !matchUsn && !matchDept) return false;
            }

            if (c.activeRiskFilter !== 'all' && st.riskClass !== c.activeRiskFilter) {
                return false;
            }

            if (c.selectedCompany && st.targetCompanies && st.targetCompanies.indexOf(c.selectedCompany) === -1) {
                return false;
            }

            if (c.selectedDepartment && st.branch !== c.selectedDepartment) {
                return false;
            }

            if (c.selectedBatch && st.batch !== c.selectedBatch) {
                return false;
            }

            return true;
        });
    };

    // -------------------------------------------------------------
    // STUDENT PROFILE & PLACEMENT INTERVENTION FORM
    // -------------------------------------------------------------
    c.openStudentModal = function(student) {
        c.selectedStudent = student;
        c.showStudentModal = true;
    };

    c.closeStudentModal = function() {
        c.showStudentModal = false;
        c.selectedStudent = null;
    };

    // AUTO-LOOKUP TRAINER FROM BACKEND TRAINING PROGRAM TABLE
    c.onTrainingProgramChange = function() {
        var selectedProgName = c.interventionForm.training_program;
        var programs = c.data.trainingPrograms || [];

        var matched = null;
        for (var i = 0; i < programs.length; i++) {
            if (programs[i].name === selectedProgName) {
                matched = programs[i];
                break;
            }
        }

        if (matched && matched.trainer) {
            c.interventionForm.trainer = matched.trainer;
        } else {
            c.interventionForm.trainer = 'Dr. Anil Varma';
        }
    };

    c.openInterventionForm = function() {
        if (!c.selectedStudent) return;

        var st = c.selectedStudent;
        var gapSkill = st.primaryGap || 'Communication';
        var currentSkillScore = (st.skills && st.skills[gapSkill] !== undefined) ? st.skills[gapSkill] : st.readiness;

        var defaultProg = (c.data.trainingPrograms && c.data.trainingPrograms.length) ? c.data.trainingPrograms[0].name : 'Interview Readiness';

        c.interventionForm = {
            training_program: defaultProg,
            trainer: '',
            intervention_type: 'Mock Interview',
            reason: 'Remediation for primary skill gap: ' + gapSkill,
            recommended_by: 'TPO',
            start_date: new Date().toISOString().split('T')[0],
            status: 'Planned',
            before_score: currentSkillScore
        };

        c.onTrainingProgramChange();
        c.showInterventionFormModal = true;
    };

    c.closeInterventionForm = function() {
        c.showInterventionFormModal = false;
    };

    // SAVE INTERVENTION TO SERVICENOW BACKEND VIA GLIDERECORD
    c.saveIntervention = function() {
        if (!c.selectedStudent) return;

        var payload = {
            action: 'create_intervention',
            student_sys_id: c.selectedStudent.sys_id,
            training_program: c.interventionForm.training_program,
            trainer: c.interventionForm.trainer,
            intervention_type: c.interventionForm.intervention_type,
            reason: c.interventionForm.reason,
            recommended_by: c.interventionForm.recommended_by,
            start_date: c.interventionForm.start_date,
            status: c.interventionForm.status,
            before_score: c.interventionForm.before_score
        };

        c.server.get(payload).then(function(response) {
            alert('Placement Intervention successfully recorded in ServiceNow backend Placement Interventions table!');
            c.showInterventionFormModal = false;

            if (c.selectedStudent) {
                if (!c.selectedStudent.interventionsList) c.selectedStudent.interventionsList = [];
                c.selectedStudent.interventionsList.unshift({
                    id: 'INTV_' + Math.floor(Math.random() * 899 + 100),
                    type: c.interventionForm.intervention_type,
                    trainingProgram: c.interventionForm.training_program,
                    trainer: c.interventionForm.trainer,
                    reason: c.interventionForm.reason,
                    status: c.interventionForm.status,
                    recommendedBy: c.interventionForm.recommended_by,
                    startDate: c.interventionForm.start_date,
                    beforeScore: c.interventionForm.before_score,
                    afterScore: '-'
                });
            }

            c.refreshData();
        });
    };

    c.refreshData = function() {
        c.server.refresh();
    };


    c.goTo = function(pageId) {
        if (!pageId) return;
        var map = {
            'dashboard': 'campus360_tpo_home',
            'home': 'campus360_tpo_home',
            'campus360_tpo_home': 'campus360_tpo_home',
            'students': 'campus360_tpo_student_management',
            'student_management': 'campus360_tpo_student_management',
            'campus360_tpo_student_management': 'campus360_tpo_student_management',
            'skills': 'campus360_tpo_skill_intelligence_new',
            'skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence_new': 'campus360_tpo_skill_intelligence_new',
            'assessments': 'student_assessments_new',
            'student_assessments': 'student_assessments_new',
            'student_assessments_new': 'student_assessments_new',
            'companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies_new': 'campus360_tpo_companies_new',
            'opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities_new': 'campus360_tpo_opportunities_new',
            'applications': 'campus360_tpo_application_new',
            'application': 'campus360_tpo_application_new',
            'campus360_tpo_application': 'campus360_tpo_application_new',
            'campus360_tpo_application_new': 'campus360_tpo_application_new',
            'interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews_new': 'campus360_tpo_interviews_new',
            'outcomes': 'campus360_tpo_placement_outcomes',
            'placement_outcomes': 'campus360_tpo_placement_outcomes',
            'campus360_tpo_placement_outcomes': 'campus360_tpo_placement_outcomes',
            'training': 'campus360_tpo_training_programs',
            'training_programs': 'campus360_tpo_training_programs',
            'campus360_tpo_training_programs': 'campus360_tpo_training_programs',
            'enrollments': 'campus360_tpo_training_programs',
            'campus360_tpo_enrollments': 'campus360_tpo_training_programs',
            'mock_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_mock_interviews': 'campus360_tpo_interviews_new',
            'risk': 'campus360_tpo_student_management',
            'campus360_tpo_risk_intelligence': 'campus360_tpo_student_management',
            'interventions': 'campus360_tpo_student_management',
            'campus360_tpo_interventions': 'campus360_tpo_student_management',
            'readiness': 'campus360_tpo_skill_intelligence_new',
            'ai_assistant': 'campus360_tpo_ai_assistant',
            'campus360_tpo_ai_assistant': 'campus360_tpo_ai_assistant'
        };
        var target = map[pageId] || pageId;
        if (typeof $window !== 'undefined' && $window.location) {
            $window.location.href = '?id=' + encodeURIComponent(target);
        } else {
            window.location.href = '?id=' + encodeURIComponent(target);
        }
    };
    c.goToPage = function(pageId) { c.goTo(pageId); };
    c.navigate = function(pageId) { c.goTo(pageId); };

};

